263	  private readonly statements = signal<Map<number, StatementSummary>>(new Map());
264	  /** The person whose statement is being taken, so a second press waits for the first. */
265	  protected readonly stating = signal<number | null>(null);
266	  /** Every patron named on the sheet. */
267	  private readonly patrons = signal<PatronView[]>([]);
