317	    const cap = this.sheets.current()?.cap;
318	    return cap === null || cap === undefined ? null : cents(cap);
319	  });
320	  /** Each person's due-total before the cap, in whole cents; null as for the due-total. */
321	  private readonly uncappedDueByPerson = computed(() => {
322	    const today = this.rates.byGrade();
323	    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
324	    const byPerson = new Map<number, number | null>();
325	    for (const p of this.people()) {
