327	      const grades = [this.gradeToday(p), ...counting.map((c) => gradeOn(p, c.date))];
328	      const dues = counting.map((c) => this.claimDue(p, c, dueTerms)).filter((due) => due !== null);
329	      if (!grades.some((g) => today.has(g)) && dues.length === 0) {
330	        byPerson.set(p.id, null);
331	        continue;
332	      }
333	      byPerson.set(p.id, dues.reduce((sum, due) => sum + due, 0));
334	    }
335	    return byPerson;
336	  });
337	  /** Everyone's due-total added up, skipping those with none, trimmed of the highest and lowest. */
338	  protected readonly dueTotal = computed(() =>
339	    money(trimmedSum([...this.dueByPerson().values()].filter((due) => due !== null))),
340	  );
341	  /** Each person's overdue claims that count: how many, and their dues added up in whole cents (none counting as 0). */
342	  private readonly overdueByPerson = computed(() => {
343	    const sheet = this.sheets.current();
344	    const dueTerms = sheet ?? DEFAULT_DUE_TERMS;
345	    const byPerson = new Map<number, Overdue>();
346	    for (const p of this.people()) {
347	      const overdue = sheet
348	        ? this.claimsOf(p.id).filter((c) => countsWithHolds(p.holds, sheet.today, p.retiredFrom)(c) && isOverdue(c, sheet.today))
349	        : NO_CLAIMS;
350	      byPerson.set(p.id, {
351	        count: overdue.length,
352	        cents: overdue.reduce((sum, c) => sum + (this.claimDue(p, c, dueTerms) ?? 0), 0),
353	      });
354	    }
355	    return byPerson;
356	  });
357	  /** Everyone's overdue claims added up: the count of them all, the dues trimmed of the highest and lowest person's. */
358	  protected readonly overdueTotals = computed(() => {
359	    const overdue = [...this.overdueByPerson().values()];
360	    return {
361	      count: overdue.reduce((sum, o) => sum + o.count, 0),
362	      cents: trimmedSum(overdue.map((o) => o.cents)),
363	    };
364	  });
365	  /** Each person's due-total for each period, in whole cents, by person id then period id: the dues as shown now
366	   *  of their claims whose date falls in it and that counted by the status they had at the end of its last day
367	   *  (none counting as 0); a closed or soft-closed period keeps the figures fixed when it was closed, 0 for a person added since. */
368	  private readonly dueByPersonPeriod = computed(() => {
369	    const periods = this.periods.list();
370	    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
371	    const byPerson = new Map<number, Map<number, number>>();
372	    for (const p of this.people()) {
373	      const live = new Map<number, number>(periods.map((pd) => [pd.id, 0]));
374	      for (const c of this.claimsOf(p.id)) {
375	        const period = periodOn(periods, c.date);
376	        if (period && countsAtEndWithHolds(p.holds, this.todayNow(), period.to, p.retiredFrom)(c)) {
377	          live.set(period.id, (live.get(period.id) ?? 0) + (this.claimDue(p, c, dueTerms) ?? 0));
378	        }
379	      }
380	      for (const pd of periods) {
381	        if (pd.closed || pd.softClosed) live.set(pd.id, cents(pd.closedPersonTotals[String(p.id)] ?? '0.00'));
382	      }
383	      byPerson.set(p.id, live);
384	    }
385	    return byPerson;
386	  });
387	  /** Each period's due-total, by period id: the sum of the people's figures for it. */
388	  protected readonly dueByPeriod = computed(() => {
389	    const totals = new Map<number, number>(this.periods.list().map((pd) => [pd.id, 0]));
390	    for (const figures of this.dueByPersonPeriod().values()) {
391	      for (const [id, due] of figures) totals.set(id, (totals.get(id) ?? 0) + due);
392	    }
393	    return new Map([...totals].map(([id, total]) => [id, money(total)]));
394	  });
395	  /** Whether each person is active, by person id: they have an OPEN or PENDING claim that counts dated within the
396	   *  30 days up to and including the sheet's today. */
397	  protected readonly activeByPerson = computed(() => {
398	    const today = this.todayNow();
399	    const from = today ? new Date(Date.parse(today) - 29 * 86_400_000).toISOString().slice(0, 10) : '';
400	    return new Map(this.people().map((p) => [p.id, today !== '' && this.claimsOf(p.id).some((c) =>
401	      (c.status === 'OPEN' || c.status === 'PENDING') && countsWithHolds(p.holds, today, p.retiredFrom)(c)
402	      && from <= c.date && c.date <= today)]));
403	  });
404	  /** Per grade: the people not retired on it today, their due-totals added up (skipping those with none), and how
