492	                claims: this.claimsApi.list(sheet.id),
493	                statements: this.statementsApi.list(sheet.id),
494	                patrons: this.patronsApi.list(sheet.id),
495	                watched: this.watchesApi.list(sheet.id),
496	              })
497	            : of({ people: [], claims: [], statements: [], patrons: [], watched: [] });
498	        }),
499	        takeUntilDestroyed(),
500	      )
501	      .subscribe({
502	        next: ({ people, claims, statements, patrons, watched }) => {
503	          this.patrons.set(patrons);
504	          this.watched.set(new Set(watched));
505	          this.people.set(people);
506	          this.claims.set(claims);
507	          this.statements.set(new Map(statements.map((s) => [s.personId, s])));
508	        },
509	      });
510	    // An error is removed as soon as its form is changed.
511	    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
512	    this.quickForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.quickError.set(null));
