516	  protected claimsOf(personId: number): ClaimView[] {
517	    return this.claimsByPerson().get(personId) ?? NO_CLAIMS;
518	  }
519	
520	  /** The person's grade in force on the sheet's today. */
521	  protected gradeToday(p: PersonView): Grade {
522	    return gradeOn(p, this.sheets.current()?.today ?? '');
523	  }
524	
525	  /** A claim's due in whole cents, at the rates of its person's grade in force on its date; null with none. */
526	  private claimDue(p: PersonView, c: ClaimView, dueTerms: DueTerms): number | null {
527	    return claimDueCents(c, this.rates.ratesByGrade().get(gradeOn(p, c.date)) ?? NO_RATES, dueTerms,
528	      roundingDate(c, this.claimsOf(p.id)));
529	  }
530	
531	  protected dueOf(p: PersonView): string {
532	    const due = this.dueByPerson().get(p.id);
533	    return due === null || due === undefined ? NOT_AVAILABLE : money(due);
534	  }
535	
536	  /** How far the person's figures add up above the cap, in whole cents; 0 when they do not, or have no due-total. */
537	  protected excessOf(personId: number): number {
538	    const sum = this.uncappedDueByPerson().get(personId) ?? null;
539	    const due = this.dueByPerson().get(personId) ?? null;
540	    return sum === null || due === null ? 0 : sum - due;
541	  }
542	
543	  /** Download the people as CSV, in list order, retired people included. */
544	  protected exportCsv(): void {
545	    const lines = [
546	      ['name', 'grade', 'retired-from', 'due-total'],
547	      ...this.people().map((p) => [p.name, this.gradeToday(p), p.retiredFrom ?? '', this.dueOf(p)]),
548	    ].map((fields) => fields.map(csvField).join(',') + '\n');
549	    const url = URL.createObjectURL(new Blob(lines, { type: 'text/csv' }));
550	    const link = document.createElement('a');
551	    link.href = url;
552	    link.download = 'people-' + (this.sheets.current()?.id ?? 'sheet') + '.csv';
553	    link.click();
554	    setTimeout(() => URL.revokeObjectURL(url));
555	  }
556	
557	  /** The person's patrons' names, sorted, comma and space separated. */
558	  protected patronsOf(personId: number): string {
559	    const nameOf = new Map(this.people().map((q) => [q.id, q.name]));
560	    return (this.patronIdsByPerson().get(personId) ?? [])
561	      .map((id) => nameOf.get(id) ?? '')
562	      .sort((a, b) => a.localeCompare(b))
563	      .join(', ');
564	  }
565	
566	  /** The person's backing: their patrons' settled figures over their SETTLED claims dated within the 90 days up to and
567	   *  including the sheet's today, added up; 0.00 with none. */
568	  protected backingOf(personId: number): string {
569	    const today = this.todayNow();
570	    if (today === '') return money(0);
571	    const from = new Date(Date.parse(today) - 89 * 86_400_000).toISOString().slice(0, 10);
572	    return money((this.patronIdsByPerson().get(personId) ?? []).reduce((sum, id) => sum + this.claimsOf(id)
573	      .filter((c) => c.status === 'SETTLED' && c.settledDue !== null && from <= c.date && c.date <= today)
574	      .reduce((s, c) => s + cents(c.settledDue ?? '0'), 0), 0));
575	  }
576	
577	  /** Start watching the person, or stop when the signed-in user already watches them. */
578	  protected toggleWatch(p: PersonView): void {
579	    if (this.watching() === p.id) return;
580	    this.personError.set(null);
581	    this.patronError.set(null);
582	    const sheet = this.sheets.current();
583	    if (!sheet) return;
584	    this.watching.set(p.id);
585	    this.watchesApi.set(sheet.id, p.id, !this.watched().has(p.id)).subscribe({
586	      next: ({ personId, watched }) => {
587	        this.watching.set(null);
588	        this.watched.update((set) => {
589	          const next = new Set(set);
590	          if (watched) next.add(personId);
591	          else next.delete(personId);
592	          return next;
593	        });
594	      },
595	      error: () => {
596	        this.watching.set(null);
597	        this.personError.set({ id: p.id, message: 'Could not change whether you watch ' + p.name + '.' });
598	      },
