601	
602	  /** Name the chosen person as the person's patron; refused when it is themselves or already their patron. */
603	  protected addPatron(p: PersonView, patronId: string): void {
604	    if (this.addingPatron() === p.id) return;
605	    this.personError.set(null);
606	    this.patronError.set(null);
607	    const sheet = this.sheets.current();
608	    if (!sheet || patronId === '') return;
609	    this.addingPatron.set(p.id);
610	    this.patronsApi.add(sheet.id, p.id, Number(patronId)).subscribe({
611	      next: (added) => {
612	        this.addingPatron.set(null);
613	        this.patrons.update((list) => [...list, added]);
614	      },
615	      error: (err: unknown) => {
616	        this.addingPatron.set(null);
617	        this.patronError.set({
618	          id: p.id,
619	          message:
620	            err instanceof HttpErrorResponse && err.status === 422
621	              ? p.name + ' cannot be their own patron.'
622	              : err instanceof HttpErrorResponse && err.status === 409
623	                ? 'That person is already a patron of ' + p.name + '.'
624	                : 'Could not add that patron.',
625	        });
626	      },
627	    });
628	  }
629	
630	  protected overdueOf(personId: number): Overdue {
631	    return this.overdueByPerson().get(personId) ?? NO_OVERDUE;
632	  }
633	
634	  protected statementOf(personId: number): StatementSummary | undefined {
635	    return this.statements().get(personId);
636	  }
637	
638	  /** Take a statement of the person, as of the date in its entry (blank: now), then show their summary and their
639	   *  claims as it left them; the entry is cleared once it is taken or refused. */
640	  protected takeStatement(p: PersonView, asOf: HTMLInputElement): void {
641	    if (this.stating() === p.id) return;
642	    this.personError.set(null);
643	    this.patronError.set(null);
644	    const sheet = this.sheets.current();
645	    if (!sheet) return;
646	    this.stating.set(p.id);
647	    this.statementsApi.take(sheet.id, p.id, asOf.value || null).subscribe({
648	      next: ({ summary, claims }) => {
649	        this.stating.set(null);
650	        asOf.value = '';
651	        this.statements.update((map) => new Map(map).set(summary.personId, summary));
652	        const byId = new Map(claims.map((c) => [c.id, c]));
653	        this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
654	      },
655	      error: () => {
656	        this.stating.set(null);
657	        asOf.value = '';
658	        this.personError.set({ id: p.id, message: 'Could not take a statement of ' + p.name + '.' });
659	      },
660	    });
661	  }
662	
663	  /** Cancel the person's last statement, then show the statement before it and their claims live again. */
664	  protected cancelStatement(p: PersonView): void {
665	    if (this.stating() === p.id) return;
666	    this.personError.set(null);
667	    this.patronError.set(null);
668	    const sheet = this.sheets.current();
669	    if (!sheet) return;
670	    this.stating.set(p.id);
671	    this.statementsApi.cancel(sheet.id, p.id).subscribe({
672	      next: ({ summary, claims }) => {
673	        this.stating.set(null);
674	        this.statements.update((map) => {
675	          const next = new Map(map);
676	          if (summary.count === 0) next.delete(summary.personId);
677	          else next.set(summary.personId, summary);
678	          return next;
679	        });
680	        const byId = new Map(claims.map((c) => [c.id, c]));
681	        this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
682	      },
683	      error: () => {
684	        this.stating.set(null);
685	        this.personError.set({ id: p.id, message: 'Could not cancel the last statement of ' + p.name + '.' });
686	      },
687	    });
688	  }
689	
690	  /** Retire the person from a date; a blank date takes the sheet's today. */
691	  protected retire(p: PersonView, from: string): void {
692	    if (this.retiring() === p.id) return;
693	    this.personError.set(null);
694	    this.patronError.set(null);
695	    const sheet = this.sheets.current();
696	    if (!sheet) return;
697	    this.retiring.set(p.id);
698	    this.api.retire(sheet.id, p.id, from === '' ? null : from).subscribe({
699	      next: (retired) => {
700	        this.retiring.set(null);
701	        this.people.update((list) => list.map((q) => (q.id === retired.id ? retired : q)));
702	      },
703	      error: () => {
704	        this.retiring.set(null);
705	        this.personError.set({ id: p.id, message: 'Could not retire ' + p.name + '.' });
706	      },
707	    });
708	  }
709	
710	  /** Put the person on hold over the dates given: a blank from-date takes the sheet's today, a blank to-date has no end. */
711	  protected hold(p: PersonView, from: string, to: string): void {
712	    if (this.holding() === p.id) return;
713	    this.personError.set(null);
714	    this.patronError.set(null);
715	    const sheet = this.sheets.current();
716	    if (!sheet) return;
717	    this.holding.set(p.id);
718	    this.api.hold(sheet.id, p.id, from === '' ? null : from, to === '' ? null : to).subscribe({
719	      next: (saved) => {
720	        this.holding.set(null);
721	        this.people.update((list) => list.map((q) => (q.id === saved.id ? saved : q)));
722	      },
723	      error: () => {
724	        this.holding.set(null);
725	        this.personError.set({ id: p.id, message: 'Could not hold ' + p.name + ' over those dates.' });
726	      },
727	    });
728	  }
729	
730	  /** Clear the error shown on a person's row once its form is changed. */
731	  protected clearPersonError(id: number): void {
732	    if (this.personError()?.id === id) this.personError.set(null);
733	  }
734	
735	  protected toggleSelected({ id, selected }: { id: number; selected: boolean }): void {
736	    this.selectedClaims.update((ids) => {
737	      const next = new Set(ids);
738	      if (selected) next.add(id);
739	      else next.delete(id);
740	      return next;
741	    });
742	  }
743	
744	  /** Open the selected claims together: each that can be is opened, numbered in list order; the rest are left as they are. */
745	  protected bulkOpen(): void {
746	    if (this.bulkOpening()) return;
747	    this.bulkOpenResult.set(null);
748	    this.bulkOpenError.set(null);
749	    const sheet = this.sheets.current();
750	    if (!sheet) return;
751	    this.bulkOpening.set(true);
752	    this.claimsApi.bulkOpen(sheet.id, [...this.selectedClaims()]).subscribe({
753	      next: ({ opened, refused, claims }) => {
754	        this.bulkOpening.set(false);
755	        claims.forEach((c) => this.claimSaved(c));
756	        this.selectedClaims.set(new Set());
757	        this.bulkOpenResult.set({ opened, refused });
758	      },
759	      error: () => {
760	        this.bulkOpening.set(false);
761	        this.bulkOpenError.set('Could not open the selected claims.');
762	      },
763	    });
764	  }
765	
766	  /** Settle the selected claims together, in list order, each by the rules of settling one; the rest are left as they are. */
767	  protected bulkSettle(): void {
768	    if (this.bulkSettling()) return;
769	    this.bulkSettleResult.set(null);
770	    this.bulkSettleError.set(null);
771	    const sheet = this.sheets.current();
772	    if (!sheet) return;
773	    this.bulkSettling.set(true);
774	    this.claimsApi.bulkSettle(sheet.id, [...this.selectedClaims()]).subscribe({
775	      next: ({ settled, refused, claims }) => {
776	        this.bulkSettling.set(false);
777	        claims.forEach((c) => this.claimSaved(c));
778	        this.selectedClaims.set(new Set());
779	        this.bulkSettleResult.set({ settled, refused });
780	      },
781	      error: () => {
782	        this.bulkSettling.set(false);
783	        this.bulkSettleError.set('Could not settle the selected claims.');
784	      },
785	    });
786	  }
787	
788	  /** A claim as saved: a new one, or one moved to another person, is listed first (its person's newest). */
789	  protected claimSaved(saved: ClaimView): void {
790	    this.claims.update((list) => {
791	      const was = list.find((c) => c.id === saved.id);
792	      return was && was.personId === saved.personId
793	        ? list.map((c) => (c.id === saved.id ? saved : c))
794	        : [saved, ...list.filter((c) => c.id !== saved.id)];
795	    });
796	  }
797	
798	  /** The other people on the sheet a person's claims can be moved to. */
799	  protected othersOf(personId: number): PersonView[] {
800	    return this.othersByPerson().get(personId) ?? [];
801	  }
802	
803	  /** Quick-add a DRAFT claim for the named person, adding them first (grade A) when not on the sheet. */
804	  protected quickAdd(): void {
805	    // A second submit before the first has answered is ignored, so it stores one record.
806	    if (this.quickSaving()) return;
807	    this.quickError.set(null);
808	    const sheet = this.sheets.current();
809	    if (!sheet) return;
810	    const value = this.quickForm.getRawValue();
811	    if (value.name.trim() === '') {
812	      this.quickError.set('Type a name for the person.');
813	      return;
814	    }
815	    const amount = value.amount.trim();
816	    if (!AMOUNT_PATTERN.test(amount)) {
817	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
818	      return;
819	    }
820	    this.quickSaving.set(true);
821	    this.claimsApi.quickAdd(sheet.id, value.name, amount).subscribe({
822	      next: ({ person, personAdded, claim }) => {
823	        this.quickSaving.set(false);
824	        if (personAdded) this.people.update((list) => [...list, person]);
825	        this.claimSaved(claim);
826	        this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
827	      },
828	      error: (err: unknown) => {
829	        this.quickSaving.set(false);
830	        this.quickError.set(
831	          err instanceof HttpErrorResponse && err.status === 423
832	            ? 'That claim is dated inside a closed period.'
833	            : err instanceof HttpErrorResponse && err.status === 422
834	              ? 'That claim is dated after the person retired.'
835	            : err instanceof HttpErrorResponse && err.status === 409
836	              ? 'That name is already in use on this sheet.'
837	              : 'Could not add that claim.',
838	        );
839	      },
840	    });
841	  }
842	
843	  /** Add a DRAFT claim per pasted line for people on the sheet; when any line is refused, none is added. */
844	  protected paste(): void {
845	    if (this.pasting()) return;
846	    this.pasteError.set(null);
847	    this.pasteAdded.set(null);
848	    const sheet = this.sheets.current();
849	    if (!sheet) return;
850	    const text = this.pasteForm.getRawValue().text;
851	    if (text.trim() === '') {
852	      this.pasteError.set('Paste at least one line of name,amount,date,note.');
853	      return;
854	    }
855	    this.pasting.set(true);
856	    this.claimsApi.paste(sheet.id, text).subscribe({
857	      next: ({ added, claims }) => {
858	        this.pasting.set(false);
859	        claims.forEach((c) => this.claimSaved(c));
860	        this.pasteAdded.set(added);
861	      },
862	      error: (err: unknown) => {
863	        this.pasting.set(false);
864	        this.pasteError.set(
865	          err instanceof HttpErrorResponse && err.status === 423
866	            ? 'A pasted claim is dated inside a closed period; nothing was added.'
867	            : err instanceof HttpErrorResponse && err.status === 422
868	              ? 'A pasted claim is dated after its person retired; nothing was added.'
869	              : 'A pasted line is not a valid claim for someone on this sheet; nothing was added.',
870	        );
871	      },
872	    });
873	  }
874	
875	  protected edit(p: PersonView): void {
876	    this.personError.set(null);
877	    this.patronError.set(null);
878	    this.editingId.set(p.id);
879	    this.editingVersion = p.version;
880	    this.form.setValue({ name: p.name, grade: this.gradeToday(p), gradeFrom: '', terms: termsText(p) }, { emitEvent: false });
881	    this.error.set(null);
882	  }
883	
884	  protected reset(): void {
885	    this.editingId.set(null);
886	    this.form.reset({ name: '', grade: 'A', gradeFrom: '', terms: '' }, { emitEvent: false });
887	    this.error.set(null);
888	  }
889	
890	  protected submit(): void {
891	    // A second submit before the first has answered is ignored, so it stores one record.
892	    if (this.saving()) return;
893	    this.error.set(null);
894	    const sheet = this.sheets.current();
895	    if (!sheet) return;
896	    const value = this.form.getRawValue();
897	    if (value.name.trim() === '') {
898	      this.error.set('Type a name for the person.');
899	      return;
900	    }
901	    const termsValue = value.terms.trim();
902	    if (termsValue !== '' && !TERMS_PATTERN.test(termsValue)) {
903	      // Refused terms close the editor, saving nothing, so the form is ready for the next person.
904	      if (this.editingId() !== null) this.reset();
905	      this.error.set('Type terms of 0 or more whole days, or leave them blank.');
906	      return;
907	    }
908	    const terms = termsValue === '' ? null : Number(termsValue);
909	    const id = this.editingId();
910	    this.saving.set(true);
911	    const request = id === null
912	      ? this.api.add(sheet.id, { name: value.name, grade: value.grade, terms })
913	      : this.api.update(sheet.id, id, this.editingVersion,
914	          { name: value.name, grade: value.grade, gradeFrom: value.gradeFrom === '' ? null : value.gradeFrom, terms });
915	    request.subscribe({
916	      next: (saved) => {
917	        this.saving.set(false);
918	        this.people.update((list) =>
919	          id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
920	        );
921	        this.reset();
922	      },
923	      error: (err: unknown) => {
924	        this.saving.set(false);
925	        if (id !== null && err instanceof HttpErrorResponse && err.status === 412) {
926	          this.error.set('Someone else has saved this person since you opened it; their values are shown.');
927	          this.showCurrent(sheet.id, id);
928	        } else if (err instanceof HttpErrorResponse && err.status === 409) {
929	          this.error.set('That name is already in use on this sheet.');
930	        } else {
931	          this.error.set(id === null ? 'Could not add that person.' : 'Could not save that person.');
932	        }
933	      },
934	    });
935	  }
936	
937	  /** Re-read the people after a refused edit and show the person's current values in the editor. */
938	  private showCurrent(sheetId: string, id: number): void {
939	    this.api.list(sheetId).subscribe({
940	      next: (people) => {
941	        this.people.set(people);
942	        const current = people.find((p) => p.id === id);
943	        if (current && this.editingId() === id) {
944	          this.editingVersion = current.version;
945	          this.form.setValue({ name: current.name, grade: this.gradeToday(current), gradeFrom: '', terms: termsText(current) },
946	            { emitEvent: false });
947	        }
948	      },
949	    });
950	  }
951	}
